uint8_t BSP_AUDIO_IN_Resume(void)
{    
  /* Call the Media layer pause/resume function */
  HAL_I2S_DMAResume(&hAudioInI2s);

  /* Return AUDIO_OK when all operations are correctly done */
  return AUDIO_OK;
}

